			encoder.SetEscapeHTML(false)
			if err := encoder.Encode(response); err != nil {
				return err
			}
		case "text", "agent":
			if position > 0 {
				// A separator, because several cards in one stream have to be tellable apart.
				fmt.Fprintln(opts.Stdout)
			}
			if len(symbols) > 1 {
				fmt.Fprintf(opts.Stdout, "== %s ==\n", symbol)
			}
