		if buffer.Len()+len(line) > maxBytes {
			break
		}
		buffer.WriteString(line)
	}
	if len(missing) > 0 {
		line := "  not defined in this repository: " + strings.Join(missing, ", ") + "\n"
		if buffer.Len()+len(line) <= maxBytes {
			buffer.WriteString(line)
		}
	}
	return []byte(buffer.String())
