+// claudeDirectlyImportsAgents recognizes a standalone @path directive outside the Markdown
+// regions where Claude suppresses imports. Ambiguous syntax returns false so the direct pointer
+// remains in place.
+func claudeDirectlyImportsAgents(claudePath, agentsPath string) (bool, error) {
+	content, err := os.ReadFile(claudePath)
+	if err != nil {
+		if os.IsNotExist(err) {
+			return false, nil
+		}
+		return false, err
+	}
+	var found, fence bool
+	var until string
+	var fenceChar byte
+	var fenceWidth int
+	for _, raw := range strings.Split(string(content), "\n") {
+		line := strings.TrimSpace(raw)
+		if until != "" {
+			if strings.Contains(line, until) {
+				until = ""
+			}
+			continue
+		}
+		if strings.Contains(line, agentPointerBegin) {
+			if !strings.Contains(line, agentPointerEnd) {
+				until = agentPointerEnd
+			}
+			continue
+		}
+		if strings.Contains(line, agentPointerEnd) {
+			return false, nil
+		}
+		if strings.Contains(line, "<!--") {
+			if !strings.Contains(line, "-->") {
+				until = "-->"
+			}
+			continue
+		}
+		if strings.Contains(line, "-->") {
+			return false, nil
+		}
+		if fence {
+			width := leadingByteRun(line, fenceChar)
+			if width >= fenceWidth && strings.TrimSpace(line[width:]) == "" {
+				fence = false
+			}
+			continue
+		}
+		if len(line) >= 3 && (strings.HasPrefix(line, "```") || strings.HasPrefix(line, "~~~")) {
+			fence, fenceChar = true, line[0]
+			fenceWidth = leadingByteRun(line, fenceChar)
+			continue
+		}
+		// Backtick spans can cross lines. Treat any non-fence backtick as ambiguous rather
+		// than risk mistaking an example for a live directive.
+		if strings.Contains(line, "`") {
+			return false, nil
+		}
+		if !strings.HasPrefix(line, "@") {
+			continue
+		}
+		imported := strings.TrimPrefix(line, "@")
+		if imported == "" || len(strings.Fields(imported)) != 1 {
+			continue
+		}
+		candidate := imported
+		if !filepath.IsAbs(candidate) {
+			candidate = filepath.Join(filepath.Dir(claudePath), candidate)
+		}
+		if filepath.Clean(candidate) == filepath.Clean(agentsPath) {
+			found = true
+		}
+	}
+	return found && until == "" && !fence, nil
+}
+
+func leadingByteRun(line string, target byte) int {
+	for i := 0; i < len(line); i++ {
+		if line[i] != target {
+			return i
+		}
+	}
+	return len(line)
+}
