+			continue
+		}
+		width := len(line[cursor:]) - len(strings.TrimLeft(line[cursor:], "`"))
+		if open == 0 {
+			open = width
+		} else if open == width {
+			open = 0
+		}
+		cursor += width
+	}
+	return open
