}

func markdownIndent(line string) int {
	indent := 0
	for i := 0; i < len(line); i++ {
		switch line[i] {
		case ' ':
			indent++
		case '\t':
			return 4
		default:
			return indent
		}
	}
	return indent
}

func nextCodeSpanWidth(line string, open int) int {
	for cursor := 0; cursor < len(line); {
		if line[cursor] != '`' {
			cursor++
			continue
		}
		width := len(line[cursor:]) - len(strings.TrimLeft(line[cursor:], "`"))
		if open == 0 {
			open = width
		} else if open == width {
			open = 0
		}
		cursor += width
	}
	return open
}

