+		t.Fatalf("init-agents error = %v, want CLAUDE.md regular-file error", err)
+	}
+	if stdout.Len() != 0 {
+		t.Fatalf("stdout was written before inspection completed: %q", stdout.String())
+	}
+	if got := readFileForTest(t, guidePath); got != string(guide) {
+		t.Fatalf("guide changed after inspection error: %q", got)
+	}
+	if got := readFileForTest(t, filepath.Join(repo, "AGENTS.md")); got != string(agents) {
+		t.Fatalf("AGENTS.md changed after inspection error: %q", got)
+	}
+}
+
+func TestInitAgentsRejectsMalformedSharedAliasWithoutWrites(t *testing.T) {
+	tests := []struct {
+		name        string
+		createAlias func(string, string) error
+	}{
