type instructionFileSnapshot struct {
	path    string
	info    os.FileInfo
	exists  bool
	content []byte
	begin   int
	end     int
}

// inspectInstructionFile resolves enough metadata to distinguish a missing file from an
// existing dangling symlink and to identify aliases before either physical file is read.
func inspectInstructionFile(path string) (instructionFileSnapshot, error) {
	snapshot := instructionFileSnapshot{path: path, begin: -1, end: -1}
	if _, err := os.Lstat(path); err != nil {
		if os.IsNotExist(err) {
			return snapshot, nil
		}
		return snapshot, fmt.Errorf("%s: inspect file: %w", path, err)
	}

	info, err := os.Stat(path)
	if err != nil {
		return snapshot, fmt.Errorf("%s: inspect existing target (is this a dangling symlink?): %w", path, err)
	}
	if !info.Mode().IsRegular() {
		return snapshot, fmt.Errorf("%s: expected a regular file, found %s", path, info.Mode().Type())
	}
	snapshot.info = info
	snapshot.exists = true
	return snapshot, nil
}

func (snapshot *instructionFileSnapshot) readAndValidate() error {
	if !snapshot.exists {
		return nil
	}
	content, err := os.ReadFile(snapshot.path)
	if err != nil {
		return fmt.Errorf("%s: read file: %w", snapshot.path, err)
	}
	begin, end, err := validatePointerMarkers(snapshot.path, content)
	if err != nil {
		return err
	}
	snapshot.content = content
	snapshot.begin = begin
	snapshot.end = end
	return nil
}

// validatePointerMarkers intentionally counts the raw marker tokens. Markers in examples,
// comments, or other Markdown regions are still managed-marker tokens and must not make the
// replacement range ambiguous.
func validatePointerMarkers(path string, content []byte) (int, int, error) {
	beginToken := []byte(agentPointerBegin)
	endToken := []byte(agentPointerEnd)
	beginCount := bytes.Count(content, beginToken)
	endCount := bytes.Count(content, endToken)
	begin := bytes.Index(content, beginToken)
	end := bytes.Index(content, endToken)

	if beginCount == 0 && endCount == 0 {
		return -1, -1, nil
	}
	if beginCount == 1 && endCount == 1 && begin < end {
		return begin, end, nil
	}

	reason := fmt.Sprintf("found %d begin marker(s) and %d end marker(s)", beginCount, endCount)
	if beginCount == 1 && endCount == 1 {
		reason = "the end marker appears before the begin marker"
	}
	return -1, -1, fmt.Errorf(
		"%s: malformed Entire Graph managed markers (%s); back up the file, preserve user-owned text, reduce it to zero markers or exactly one complete %q / %q pair with begin before end, then rerun init-agents",
		path, reason, agentPointerBegin, agentPointerEnd,
	)
}

